const test=require('node:test');
const assert=require('node:assert/strict');
require('./terrain-data.js');
const E=require('./engine.js');
const rawFresh=(n=1,seed=20260917)=>E.newGame({players:n,seed},global.DINO_TERRAIN);
const fresh=(n=1,seed=20260917)=>placeAll(rawFresh(n,seed));
const apply=(g,t,a)=>{const s=E.clone(g);E.act(s,t,a);return s;};
function fixture(n=1){const g=fresh(n);for(const p of g.players)p.hand=['explore','gather','gather','run'];const kinds=['forest','plain','stream','bush','cave','forest'];E.neighbors('0,0').forEach((k,i)=>g.tiles[k]={id:'fixture'+i,terrain:kinds[i],resources:['branch','stone','berry','stem'],level:1,safe:false,hunt:null});return g;}
function supplies(g,kinds,p=g.players[0]){for(const k of kinds)assert.ok(E.addItem(g,p,k),'fixture item fits: '+k);return g;}
function placeAll(g){if(g.huntResult)E.act(g,'confirmHuntResult');while(g.loot.length){const owner=E.lootOwner(g),item=g.loot[0];let fit;for(let r=0;r<4&&!fit;r++)for(const cell of E.bagCells(owner))if(E.bagFits(owner,{...item,rotation:r},cell.x,cell.y)){fit={x:cell.x,y:cell.y,rotation:r};break;}assert.ok(fit,'test loot has space');E.act(g,'placeLoot',fit);}return g;}

function travel(g,type,data){return apply(g,type,data);}
// Explicit fixture for saves written before v0.18, after the movement cost was paid.
function legacyDeparture(g=fixture(2),to='1,0',running=false){
 const p=g.players[g.turn],card=p.hand.shift();p.discard.push(card);g.actions--;
 const item={id:'i'+g.serial++,kind:'berry',owner:p.id,origin:'0,0',source:'camp-departure',rotation:0,flip:false};
 g.loot.push(item);g.pendingDeparture={player:p.id,from:'0,0',to,running,label:'',lootId:item.id};return g;
}
function resolveBoarAttack(g){g.actionDeck=[{order:'ABC',giant:'D'}];g=apply(g,'battlePlan',{cards:[0,1,2]});for(let i=0;i<3;i++)g=apply(g,'battleStep');return g;}
function fillTile(g){while(g.tileSetup)E.act(g,'supplyTile',{kind:g.tileSetup.remaining[0],to:g.tileSetup.tile});return g;}
function paid(g,type,data){const next=E.clone(g);E.act(next,'beginPayment',{type,data});const tray=next.payment,chosen=new Set;for(const id of tray.requiredIds){E.act(next,'offerPayment',{id});chosen.add(id);}for(const [kind,n] of Object.entries(tray.cost)){let have=[...chosen].filter(id=>next.players[next.turn].bag.find(i=>i.id===id)?.kind===kind).length;for(const item of next.players[next.turn].bag.filter(i=>i.kind===kind&&!i.topping&&!chosen.has(i.id))){if(have>=n)break;E.act(next,'offerPayment',{id:item.id});chosen.add(item.id);have++;}}E.act(next,'commitPayment');return next;}
function gatherOne(g,card,index=0){const next=E.clone(g);E.act(next,'startGather',{card});const item={kind:next.tiles[next.players[next.turn].pos].resources[index]};let fit;for(let r=0;r<4&&!fit;r++)for(const c of E.bagCells(next.players[next.turn]))if(E.bagFits(next.players[next.turn],{...item,rotation:r},c.x,c.y)){fit={x:c.x,y:c.y,rotation:r};break;}assert.ok(fit);E.act(next,'gatherTake',{index,...fit});if(next.gathering)E.act(next,'finishGather');return next;}

test('new game: only base camp, all terrain retained, actual shuffled 12 → hand 4',()=>{
  const a=rawFresh(4),b=rawFresh(4);assert.deepEqual(a,b);assert.equal(a.version,2);assert.deepEqual(Object.keys(a.tiles),['0,0']);assert.equal(a.terrainDeck.length,36);assert.equal(a.terrainDeck.filter(t=>t.terrain==='escape').length,1);
  assert.deepEqual(a.terrainDeck.filter(t=>t.id!=='exit').map(t=>t.id).sort(),global.DINO_TERRAIN.map(t=>t.id).sort());
  for(const [i,p] of a.players.entries()){assert.equal(p.pos,'0,0');assert.equal(p.hand.length,4);assert.equal(p.deck.length,8);assert.deepEqual([...p.hand,...p.deck].sort(),E.BASIC_DECK.slice().sort());assert.deepEqual(p.hand,a.setupDecks[i].slice(-4).reverse());assert.deepEqual(p.deck,a.setupDecks[i].slice(0,8));assert.equal(p.combatHand.length,4);assert.equal(p.bag.length,0);assert.deepEqual(a.loot,[]);assert.equal(a.actions,2);assert.equal(a.pendingDeparture,null);assert.deepEqual(p.bagUnlocks,[]);}
  const hands=new Set(Array.from({length:20},(_,i)=>JSON.stringify(fresh(1,100+i).players[0].hand)));assert.ok(hands.size>5,'initial hand is shuffled, not fixed');
});
test('backpack exactly follows original 21-slot silhouette and nine locks',()=>{
  const p=fresh().players[0],cells=E.bagCells(p);assert.equal(E.BAG.width,5);assert.equal(E.BAG.height,5);assert.equal(cells.length,21);assert.equal(cells.filter(c=>!c.locked).length,12);assert.equal(cells.filter(c=>c.locked).length,9);
  const rows=Array.from({length:5},(_,y)=>Array.from({length:5},(_,x)=>{const c=cells.find(c=>c.x===x&&c.y===y);return !c?'.':c.locked?'L':'O';}).join(''));assert.deepEqual(rows,['.LLL.','.OOO.','LOOOL','LOOOL','LOOOL']);
  assert.equal(E.bagFits(p,{id:'q',kind:'stone'},0,0),false);assert.equal(E.bagFits(p,{id:'q',kind:'stone'},1,0),false);assert.equal(E.bagFits(p,{id:'q',kind:'stone'},0,2),false);assert.equal(E.bagFits(p,{id:'q',kind:'stone'},3,4),true);assert.equal(E.bagFits(p,{id:'q',kind:'stone'},1.1,2),false);
});
test('gather drags directly from tile to bag; failed drops consume nothing and one card covers three',()=>{
  let g=fixture();g.players[0].pos='1,0';const before=g.tiles['1,0'].resources.length;g=apply(g,'startGather',{card:1});assert.equal(g.actions,2);assert.equal(g.players[0].hand.length,4);assert.equal(g.players[0].detection,0);assert.equal(g.players[0].bag.length,0);const snapshot=E.clone(g);assert.throws(()=>E.act(g,'gatherTake',{index:0,x:0,y:0}),/가방/);assert.deepEqual(g,snapshot);g=apply(g,'gatherTake',{index:0,x:1,y:2});assert.equal(g.actions,1);assert.equal(g.players[0].hand.length,3);assert.equal(g.players[0].detection,1);assert.equal(g.gathering.taken,1);assert.equal(g.loot.length,0);assert.throws(()=>apply(g,'end'),/채집/);g=apply(g,'gatherTake',{index:0,x:3,y:1});g=apply(g,'gatherTake',{index:0,x:2,y:2});assert.equal(g.gathering,null);assert.equal(g.tiles['1,0'].resources.length,before-3);assert.equal(g.players[0].bag.length,3);assert.equal(g.actions,1);assert.equal(g.players[0].detection,1);
});
test('branches occupy one cell while multi-cell gear rotates and flips; invalid moves preserve items',()=>{
  let g=fresh(),p=g.players[0];p.bag=[];supplies(g,['branch','battery','spear']);const branch=p.bag.find(i=>i.kind==='branch'),battery=p.bag.find(i=>i.kind==='battery');assert.deepEqual(E.itemCells(branch),[[0,0]]);
  g=apply(g,'bagMove',{id:branch.id,x:3,y:4,rotation:1});assert.deepEqual(E.itemCells(g.players[0].bag.find(i=>i.id===branch.id)),[[0,0]]);assert.equal(g.actions,2);
  assert.throws(()=>apply(g,'bagMove',{id:branch.id,x:battery.x,y:battery.y,rotation:1}),/그 칸/);assert.throws(()=>apply(g,'bagMove',{id:branch.id,x:0,y:0}),/그 칸/);
  const normal=E.itemCells({...battery,rotation:0,flip:false}).map(v=>v.join(',')).sort();const flipped=E.itemCells({...battery,rotation:0,flip:true}).map(v=>v.join(',')).sort();assert.notDeepEqual(normal,flipped);assert.equal(E.itemCells({kind:'spear',rotation:1}).length,3);
});
test('exploring awaits movement choice; camp-only start exposes six reachable slots',()=>{
  let g=fresh();g.players[0].hand=['explore','explore','gather','run'];assert.equal(E.exploreTargets(g).length,6);assert.throws(()=>apply(g,'explore',{card:0,to:'1,0',level:2}));g=apply(g,'explore',{card:0,to:'1,0',level:1});assert.equal(g.players[0].pos,'0,0');assert.equal(Object.keys(g.tiles).length,2);fillTile(g);g=travel(g,'resolveExplore',{move:true});assert.equal(g.players[0].pos,'1,0');g=apply(g,'explore',{card:0,to:'2,0',level:2});assert.equal(g.tiles['2,0'].level,2);assert.ok(g.tiles['2,0'].resourcePlan.includes('metal'));assert.ok(g.tiles['2,0'].hunt);assert.throws(()=>apply(fresh(),'explore',{card:0,to:'9,0',level:1}));
});
