test('bag overflow stays at its origin and is recovered by gathering after manual rearrangement',()=>{
  let g=fresh();g.players[0].bag=[];supplies(g,Array(12).fill('stone'));g.loot=[{id:'waiting',kind:'battery',owner:0,origin:'0,0',rotation:0,flip:false}];g=apply(g,'end');assert.equal(g.loot.length,0);assert.equal(E.groundItems(g,'0,0')[0].id,'waiting');assert.equal(g.round,2);
  for(const pos of [[1,1],[1,2],[2,2]]){const item=g.players[0].bag.find(i=>i.x===pos[0]&&i.y===pos[1]);g=apply(g,'discardItem',{id:item.id});assert.ok(E.groundItems(g,'0,0').some(i=>i.id===item.id));}
  g.players[0].hand[0]='gather';g=apply(g,'startGather',{card:0});const before=E.clone(g);assert.throws(()=>E.act(g,'gatherTake',{groundId:'waiting',x:1,y:0}),/가방/);assert.deepEqual(g,before);g=apply(g,'gatherTake',{groundId:'waiting',tile:'0,0',x:1,y:1});assert.equal(E.groundItems(g,'0,0').length,3);assert.ok(g.players[0].bag.some(i=>i.id==='waiting'));assert.equal(g.actions,1);
});

