test('two-player hunt: assist is spent, loot queues each owner, unused plans return',()=>{let g=fixture(2);g.players[0].pos=g.players[1].pos='1,-1';g.tiles['1,-1'].hunt={kind:'deer',hp:2};E.encounter(g,g.tiles['1,-1']);g=apply(g,'battleAssist',{player:1,card:0});g=apply(g,'battlePlan',{cards:[0,1,2]});g=apply(g,'battleStep');assert.equal(g.battle,null);assert.deepEqual(g.loot.map(i=>[i.kind,i.owner]),[['meat',0],['herb',0],['meat',1]]);placeAll(g);assert.equal(E.count(g.players[0],'meat'),1);assert.equal(E.count(g.players[1],'meat'),1);assert.equal(E.count(g.players[0],'herb'),1);assert.equal(g.players[1].combatHand.length,4);assert.equal(g.players[1].combatDiscard.length,1);});
