  g=apply(g,'beginPayment',{type:'cook',data:{card:0,items:[fish[1].id]}});g=apply(g,'offerPayment',{id:fish[1].id});g=apply(g,'offerPayment',{id:fuels[1].id});g=E.migrateSave(JSON.parse(JSON.stringify(g)));assert.deepEqual(g.payment.offered,[fish[1].id,fuels[1].id]);g=apply(g,'commitPayment');assert.equal(g.payment,null);assert.equal(g.actions,1);assert.ok(g.players[0].bag.some(i=>i.id===fuels[0].id));assert.ok(g.players[0].bag.some(i=>i.id===fish[0].id));assert.ok(!g.players[0].bag.some(i=>i.id===fuels[1].id));assert.deepEqual(g.players[0].bag.find(i=>i.id===fish[1].id),{...fish[1],kind:'cookedFish'});assert.deepEqual(g.loot,[]);assert.equal(E.count(g.players[0],'cookedFish'),1);assert.throws(()=>apply(g,'commitPayment'),/지불/);
