function assembleAircraft(g,owner=(kind)=>0){
  for(const zone of E.AIRCRAFT_ZONES)for(let i=0;i<zone.slots.length;i++){if(!zone.slots[i]||g.aircraft.zones[zone.id].cells[i])continue;const kind=zone.slots[i],player=owner(kind,zone.id,i);g.turn=player;const p=g.players[player];assert.equal(p.pos,'0,0');assert.ok(E.addItem(g,p,kind));const item=p.bag.at(-1);E.act(g,'installAircraft',{id:item.id,zone:zone.id,x:i%zone.w,y:Math.floor(i/zone.w),rotation:0,flip:false});}return g;
}
