const BUILDING_SOLUTIONS={"pack1":[{"material":"wood","shape":"D2","rotation":0,"flip":false,"x":0,"y":1},{"material":"wood","shape":"Z","rotation":0,"flip":false,"x":1,"y":0},{"material":"wood","shape":"D2","rotation":0,"flip":false,"x":3,"y":0},{"material":"wood","shape":"Z","rotation":0,"flip":false,"x":5,"y":0},{"material":"fiber","shape":"D2","rotation":0,"flip":false,"x":7,"y":0},{"material":"fiber","shape":"D2","rotation":0,"flip":false,"x":8,"y":1}],"kitchen":[{"material":"wood","shape":"U5","rotation":1,"flip":false,"x":1,"y":0},{"material":"stone","shape":"D2","rotation":1,"flip":false,"x":0,"y":1},{"material":"stone","shape":"D2","rotation":0,"flip":false,"x":1,"y":3},{"material":"wood","shape":"V3","rotation":2,"flip":false,"x":2,"y":1}],"workshop":[{"material":"wood","shape":"U5","rotation":0,"flip":false,"x":1,"y":2},{"material":"fiber","shape":"D2","rotation":1,"flip":false,"x":4,"y":2},{"material":"wood","shape":"V3","rotation":1,"flip":false,"x":0,"y":1},{"material":"fiber","shape":"T","rotation":0,"flip":false,"x":1,"y":0},{"material":"fiber","shape":"D","rotation":0,"flip":false,"x":3,"y":1},{"material":"fiber","shape":"D","rotation":0,"flip":false,"x":4,"y":1}],"warehouse":[{"material":"wood","shape":"U5","rotation":1,"flip":false,"x":0,"y":0},{"material":"wood","shape":"D2","rotation":1,"flip":false,"x":2,"y":0},{"material":"wood","shape":"D","rotation":0,"flip":false,"x":2,"y":2}]};
test('all four buildings can be crafted and completed together while retaining their limited bonus pieces',()=>{
  let g=processFixture();let bonusCount=0;for(const def of E.BUILDINGS){for(const plan of BUILDING_SOLUTIONS[def.id]){g.players[0].bag=[];g.players[0].hand=['explore'];g.actions=2;supplies(g,Array(E.pieceCost(plan.material,plan.shape)).fill(E.MATERIALS[plan.material].raw));g=paid(g,'process',{cards:[0],recipes:[{material:plan.material,shape:plan.shape}]});g=apply(g,'place',{source:'pending',board:def.id,x:plan.x,y:plan.y,rotation:plan.rotation,flip:plan.flip});while(g.pending.length){const bonus=g.pending[0];let fit;for(let rotation=0;rotation<4&&!fit;rotation++)for(let y=0;y<3&&!fit;y++)for(let x=0;x<3;x++)if(E.canPlace(g.players[0],{...bonus,rotation},'storage',x,y)){fit={x,y,rotation};break;}assert.ok(fit,'bonus must fit retained storage');g=apply(g,'place',{source:'pending',board:'storage',...fit});bonusCount++;}while(g.loot.length)g=apply(g,'discardLoot');}const b=g.players[0].boards.find(b=>b.id===def.id);assert.equal(b.complete,true);assert.ok(b.bonuses.every(b=>b.claimed));assert.equal(b.cells.filter(Boolean).length,def.mask.filter(Boolean).length);}
  assert.equal(bonusCount,3);assert.equal(g.players[0].boards.filter(b=>b.complete).length,4);assert.equal(g.players[0].capacity,21);assert.equal(g.players[0].vp,8);assert.equal(g.players[0].storage.length,2);assert.equal(E.pieceStock(g,'wood','D'),0);assert.equal(E.pieceStock(g,'fiber','T'),2);assert.equal(E.pieceStock(g,'wood','Z'),1);assert.ok(Object.values(g.pieceSupply).every(n=>n>=0&&n<=3));assert.deepEqual(E.migrateSave(g),g);
});
