  const expanded=useLegacyPacks(fresh());expanded.players[0].capacity=15;expanded.players[0].bagUnlocks=[];const restored=E.migrateSave(expanded);assert.equal(restored.players[0].boards.filter(b=>b.legacyPack).length,3,'existing expansion alone protects the old trio');assert.equal(restored.players[0].capacity,15);assert.deepEqual(restored.players[0].bagUnlocks,['top']);
