// A three-card combat round spends one action; returning to the map does not spend another.
function roundFixture(players=1,actions=2){const g=E.migrateSave(fixture(players)),p=g.players[0];p.pos='1,0';p.combatHand=['crouch','crouch','crouch','punch'];g.actions=actions;g.tiles[p.pos].level=2;g.tiles[p.pos].hunt={kind:'boar',hp:7};E.encounter(g,g.tiles[p.pos]);g.battle.pattern=['B','B','B'];return g;}
function playRound(g){g=apply(g,'battlePlan',{cards:[0,1,2]});for(let i=0;i<3&&g.battle?.stage==='resolve';i++)g=apply(g,'battleStep');return g;}
test('combat spends one action on commitment, never per card, and rejects duplicate commitments atomically',()=>{
 let g=roundFixture(),hand=g.players[0].hand.slice();const bad=E.clone(g);assert.throws(()=>E.act(g,'battlePlan',{cards:[0,0,1]}));assert.deepEqual(g,bad);g=apply(g,'battlePlan',{cards:[0,1,2]});assert.equal(g.actions,1);assert.deepEqual(g.players[0].hand,hand);const committed=E.clone(g);assert.throws(()=>E.act(g,'battlePlan',{cards:[0,1,2]}));assert.deepEqual(g,committed);for(let i=0;i<3;i++){g=apply(g,'battleStep');assert.equal(g.actions,1);assert.equal(g.players[0].hunger,6);}assert.equal(g.battle.stage,'choice');assert.equal(g.battle.round,2);assert.throws(()=>apply(g,'battlePlan',{cards:[0,1,2]}),/단계/);
});
test('second combat round spends final action then ends turn and hunger exactly once',()=>{
 let g=playRound(roundFixture(2));const hp=g.battle.hp;g=apply(g,'battleContinue');assert.equal(g.actions,1);g.players[0].combatHand=['crouch','crouch','crouch','punch'];g=playRound(g);assert.equal(g.battle,null);assert.equal(g.turn,1);assert.equal(g.actions,2);assert.equal(g.players[0].hunger,5);assert.equal(g.players[1].hunger,6);assert.equal(g.tiles['1,0'].hunt.hp,hp);assert.equal(g.tiles['1,0'].hunt.resume.prepared,1);assert.equal(g.tiles['1,0'].hunt.resume.round,3);assert.equal(g.players[0].combatHand.length,4);
});
