test('full fragmented bag can craft, save, rearrange and receive without dropping the completed item',()=>{
  let g=fillBagExcept(fixture(2),[]);g.players[0].pos='1,0';const p=g.players[0];p.bag.forEach(i=>i.kind='berry');
  for(const [n,cell] of [[1,1],[2,2],[3,3]].entries())p.bag.find(i=>i.x===cell[0]&&i.y===cell[1]).kind=['branch','stone','stem'][n];
  g=paid(g,'craft',{card:0});const made=g.loot[0];assert.equal(made.kind,'spear');assert.equal(made.source,'crafted');assert.equal(E.canFitItem(g.players[0],made),false);assert.equal(g.actions,1);assert.equal(g.players[0].hand.length,3);assert.equal(E.groundItems(g,'1,0').length,0);
  g=E.migrateSave(JSON.parse(JSON.stringify(g)));assert.deepEqual(g.loot,[made]);const before=E.clone(g);assert.throws(()=>E.act(g,'end'),/가방 배치/);assert.deepEqual(g,before);g=apply(g,'autoCollectLoot');assert.deepEqual(g.loot,[made]);
  const moved=g.players[0].bag.find(i=>i.x===2&&i.y===1);g=apply(g,'bagMove',{id:moved.id,x:2,y:2});const dropped=g.players[0].bag.find(i=>i.x===3&&i.y===1);g=apply(g,'discardItem',{id:dropped.id});assert.equal(E.groundItems(g,'1,0')[0].id,dropped.id);
  g=apply(g,'placeLoot',{id:made.id,x:1,y:1,rotation:1});assert.equal(g.actions,1);assert.equal(g.players[0].hand.length,3);assert.equal(g.loot.length,0);assert.equal(g.players[0].bag.find(i=>i.id===made.id).source,undefined);
  const stored=E.clone(g);assert.throws(()=>E.act(g,'placeLoot',{id:dropped.id,x:3,y:3}));assert.throws(()=>E.act(g,'gatherTake',{groundId:dropped.id,x:3,y:3}),/진행 중인 채집/);assert.deepEqual(g,stored);
  g=apply(g,'startGather',{card:0});g=apply(g,'gatherTake',{groundId:dropped.id,x:3,y:3});assert.equal(g.actions,0);assert.equal(g.players[0].hand.length,2);assert.equal(g.players[0].detection,1);assert.equal(E.groundItems(g,'1,0').length,0);assert.equal(g.players[0].bag.find(i=>i.id===dropped.id).kind,dropped.kind);assert.deepEqual(E.migrateSave(g),g);
});
