const planeSteelSolution=[{"shape": "S", "rotation": 0, "flip": false, "x": 6, "y": 1}, {"shape": "L", "rotation": 3, "flip": true, "x": 4, "y": 3}, {"shape": "S", "rotation": 0, "flip": true, "x": 5, "y": 8}, {"shape": "S", "rotation": 1, "flip": true, "x": 7, "y": 6}, {"shape": "I", "rotation": 0, "flip": false, "x": 4, "y": 6}, {"shape": "S", "rotation": 0, "flip": true, "x": 7, "y": 3}, {"shape": "S", "rotation": 0, "flip": true, "x": 9, "y": 3}, {"shape": "T", "rotation": 2, "flip": false, "x": 11, "y": 4}, {"shape": "S", "rotation": 0, "flip": true, "x": 9, "y": 5}, {"shape": "S", "rotation": 0, "flip": false, "x": 0, "y": 4}, {"shape": "T", "rotation": 2, "flip": false, "x": 1, "y": 5}, {"shape": "O", "rotation": 0, "flip": false, "x": 3, "y": 4}];

test('aircraft has one connected 60-cell footprint and all 48 steel cells tile with twelve tetrominoes',()=>{
  let g=fresh(2),layout=E.aircraftCells();assert.equal(layout.length,60);assert.equal(new Set(layout.map(c=>`${c.x},${c.y}`)).size,60);
  const left=new Set(layout.map(c=>`${c.x},${c.y}`)),queue=[left.values().next().value];left.delete(queue[0]);for(let i=0;i<queue.length;i++){const[x,y]=queue[i].split(',').map(Number);for(const[dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const k=`${x+dx},${y+dy}`;if(left.delete(k))queue.push(k);}}assert.equal(left.size,0);
  let crossing=false;for(const [n,step]of planeSteelSolution.entries()){g.turn=n%2;const p=E.active(g),id=`puzzle-steel-${n}`;p.bag.push({id,kind:'steel',steelShape:step.shape,x:1,y:1,rotation:0,flip:false});const used=E.itemCells({kind:'steel',steelShape:step.shape,rotation:step.rotation,flip:step.flip}).map(([x,y])=>layout.find(c=>c.x===step.x+x&&c.y===step.y+y));crossing ||=new Set(used.map(c=>c.zone)).size>1;g=apply(g,'installAircraft',{id,zone:'grid',...step});assert.equal(g.actions,2);assert.equal(E.aircraftProgress(g).filled,(n+1)*4);}
  assert.equal(crossing,true);assert.equal(Object.values(g.aircraft.contributions).reduce((a,b)=>a+b),48);assert.deepEqual(E.migrateSave(g).aircraft,g.aircraft);
  for(const [kind,x,y]of [['engine',5,0],['battery',5,4],['battery',7,4],['cooler',5,7]]){const p=E.active(g);assert.ok(E.addItem(g,p,kind));g=apply(g,'installAircraft',{id:p.bag.at(-1).id,zone:'grid',x,y});}assert.deepEqual(E.aircraftProgress(g),{filled:60,total:60,ready:true});assert.equal(Object.values(g.aircraft.contributions).reduce((a,b)=>a+b),68);assert.deepEqual(E.migrateSave(g).aircraft,g.aircraft);g=apply(g,'departAircraft');assert.equal(g.ended,true);assert.deepEqual(E.migrateSave(g),g);
});
test('each steel shape costs two ingredients and one action, retains its four-cell identity through receipt/drop/pickup',()=>{
 for(const steelShape of E.AIRCRAFT_STEEL_SHAPES){let g=supplies(fresh(),['metal','branch']);g=paid(g,'aircraftCraft',{recipe:'steel',steelShape,card:0});assert.equal(g.loot.length,1);const item=g.loot[0];assert.equal(item.steelShape,steelShape);assert.equal(E.itemCells(item).length,4);assert.equal(g.actions,1);assert.equal(g.players[0].hand.length,3);g=apply(g,'autoCollectLoot');assert.equal(g.loot.length,0);assert.equal(g.players[0].bag[0].steelShape,steelShape);g=apply(g,'discardItem',{id:item.id});assert.equal(E.groundItems(g,'0,0')[0].steelShape,steelShape);g.players[0].hand[0]='gather';g=apply(g,'startGather',{card:0});g=apply(g,'autoGather');assert.equal(g.players[0].bag[0].steelShape,steelShape);assert.equal(g.actions,0);assert.deepEqual(E.migrateSave(g),g);}
 const g=supplies(fresh(),['metal','branch']),before=E.clone(g);assert.throws(()=>E.act(g,'beginPayment',{type:'aircraftCraft',data:{recipe:'steel',steelShape:'U5',card:0}}),/모양/);assert.deepEqual(g,before);
});
test('a cross-region steel piece cannot overlap, bridge empty space or evade save validation',()=>{
 const g=fresh();g.players[0].bag.push({id:'steel-I',kind:'steel',steelShape:'I',x:1,y:1,rotation:1,flip:false});const bad=[{x:0,y:0},{x:4,y:2},{x:-1,y:5},{x:13,y:5},{x:5,y:0}];for(const pos of bad){const before=E.clone(g);assert.throws(()=>E.act(g,'installAircraft',{id:'steel-I',zone:'grid',...pos,rotation:0}));assert.deepEqual(g,before);}
 E.act(g,'installAircraft',{id:'steel-I',zone:'grid',x:4,y:3,rotation:0});assert.equal(E.aircraftProgress(g).filled,4);assert.equal(g.aircraft.contributions[0],4);assert.equal(new Set(E.aircraftCells().filter(c=>g.aircraft.zones[c.zone].cells[c.index]?.id==='steel-I').map(c=>c.zone)).size,2);const badSave=E.clone(g);badSave.aircraft.zones.engine.cells[12]=null;assert.throws(()=>E.migrateSave(badSave),/모양/);
});
function oldAircraftSave(complete=false){const g=fresh(2),defs=[['engine',3,['engine','engine','steel','engine','engine','steel','steel','steel','steel']],['wingLeft',4,Array(8).fill('steel')],['wingRight',4,Array(8).fill('steel')],['cooling',3,['cooler','cooler','steel','steel','steel','steel']],['power',2,['battery','steel','battery','battery']]];g.aircraft={zones:Object.fromEntries(defs.map(([id,w,slots])=>[id,{cells:Array(slots.length).fill(null)}])),contributions:{0:0,1:0},ready:false,departed:false,scores:[]};let serial=0;for(const[zone,w,slots]of defs)for(let i=0;i<slots.length;i++){if(g.aircraft.zones[zone].cells[i])continue;const kind=slots[i];if(!complete&&kind!=='engine'&&!(zone==='wingLeft'&&i===0))continue;const id=`old-plane-${serial++}`,owner=kind==='engine'?0:1;for(const[x,y]of E.itemCells({kind})){const at=i+y*w+x;g.aircraft.zones[zone].cells[at]={id,kind,owner};}g.aircraft.contributions[owner]+=E.AIRCRAFT_POINTS[kind];}return g;}
test('35-cell saved aircraft migrates once without losing installed identities, owners or contribution',()=>{
 const old=oldAircraftSave(),parts=Object.values(old.aircraft.zones).flatMap(z=>z.cells).filter(Boolean),g=E.migrateSave(old);assert.equal(g.aircraft.layoutVersion,2);assert.equal(E.aircraftProgress(g).filled,5);assert.equal(E.aircraftProgress(g).total,60);assert.deepEqual(g.aircraft.contributions,old.aircraft.contributions);assert.deepEqual(Object.values(g.aircraft.zones).flatMap(z=>z.cells).filter(Boolean).sort((a,b)=>a.id.localeCompare(b.id)),parts.sort((a,b)=>a.id.localeCompare(b.id)));assert.deepEqual(E.migrateSave(g),g);
 const full=oldAircraftSave(true);full.aircraft.ready=true;const migrated=E.migrateSave(full);assert.equal(E.aircraftProgress(migrated).filled,35);assert.equal(migrated.aircraft.ready,false);assert.deepEqual(migrated.aircraft.contributions,full.aircraft.contributions);
 full.aircraft.departed=true;full.ended=true;full.winner=1;full.winners=[1];full.players[1].vp=35;full.aircraft.scores=[{player:1,base:0,contribution:35,total:35,rank:1},{player:0,base:0,contribution:6,total:6,rank:2}];const ended=E.migrateSave(full);assert.equal(ended.ended,true);assert.equal(ended.winner,1);assert.equal(ended.players[1].vp,35);assert.deepEqual(ended.aircraft.scores,full.aircraft.scores);assert.deepEqual(E.aircraftProgress(ended),{filled:35,total:35,ready:true});assert.deepEqual(E.migrateSave(ended),ended);
});

test('material-exclusive zigzags remain distinct under rotation and construction mirroring is atomic',()=>{
  const signature=cells=>JSON.stringify(cells.slice().sort(([x,y],[a,b])=>y-b||x-a));
  const woodRotations=new Set([0,1,2,3].map(r=>signature(E.shape('Z',r,false))));
  for(let r=0;r<4;r++)assert.equal(woodRotations.has(signature(E.shape('S',r,false))),false);
  for(const recipe of E.PIECE_RECIPES){let g=processFixture();supplies(g,Array(recipe.cost).fill(E.MATERIALS[recipe.material].raw));g=paid(g,'process',{cards:[0],recipes:[recipe]});const p=E.active(g),piece=g.pending[0];assert.equal(E.canPlace(p,{...piece,flip:true},'storage',0,0),false);const before=E.clone(g);assert.throws(()=>E.act(g,'place',{source:'pending',board:'storage',x:0,y:0,flip:true}),/회전만/);assert.deepEqual(g,before);assert.equal(E.canPlace(p,{...piece,rotation:1},'storage',0,0),true);g=apply(g,'place',{source:'pending',board:'storage',x:0,y:0,rotation:1});assert.equal(E.active(g).storage[0].cells.filter(Boolean).length,E.SHAPES[recipe.shape].length);assert.deepEqual(E.migrateSave(g),g);}
});
test('single and domino recipes share finite stocks with bonuses and cannot substitute materials',()=>{
  for(const material of ['wood','stone','fiber'])for(const shape of ['D','D2']){let g=processFixture();const raw=E.MATERIALS[material].raw,cost=shape==='D'?2:3;supplies(g,Array(cost).fill(raw));g=paid(g,'process',{cards:[0],recipes:[{material,shape}]});assert.equal(E.count(E.active(g),raw),0);assert.equal(g.actions,1);assert.equal(g.pending.length,1);assert.equal(E.pieceCells(g.pending[0]).length,shape==='D'?1:2);assert.equal(E.pieceStock(g,material,shape),2);g=apply(g,'discardPiece',{source:'pending'});assert.equal(E.pieceStock(g,material,shape),3);}
});

function weaponBattle(players=1){const g=E.migrateSave(fixture(players));for(const p of g.players)p.pos='1,0';g.tiles['1,0'].hunt={kind:'turtle',hp:20};E.encounter(g,g.tiles['1,0']);g.battle.maxHp=20;g.battle.pattern=['B','B','B'];return g;}
function combatPile(p){return [...p.combatHand,...p.combatDeck,...p.combatDiscard];}
test('bag weapons create individual attack options without changing the four-card hand',()=>{
  let g=supplies(fresh(),['knife','spear']);const p=g.players[0],before=E.clone(p.combatHand),knife=p.bag.find(i=>i.kind==='knife');assert.deepEqual(E.combatOptions(p).map(o=>E.combatCardData(o.card).name),['맨손 공격','웅크리기','힘껏 치기','맨손 공격','칼찌르기','창찌르기']);assert.deepEqual(p.combatHand,before);knife.durability=0;assert.equal(E.combatOptions(p).length,5);knife.durability=3;g=apply(g,'discardItem',{id:knife.id});assert.equal(E.combatOptions(g.players[0]).length,5);assert.equal(E.groundItems(g,'0,0')[0].kind,'knife');g.loot=[{id:'not-received',kind:'knife',owner:0,origin:'0,0',durability:6}];assert.equal(E.combatOptions(g.players[0]).length,5);
});
test('basic attacks neither borrow weapon damage nor consume any weapon durability',()=>{
  let g=supplies(weaponBattle(),['knife','spear']);g=apply(g,'battlePlan',{cards:[0,1,2]});g=apply(g,'battleStep');assert.equal(g.battleEffect.power,1);assert.equal(g.battleEffect.damage,1);assert.deepEqual(g.battleEffect.weapons,[]);assert.deepEqual(g.players[0].bag.map(i=>i.durability),[6,6]);
});
test('weapon cards mix with the basic hand, wear only their own item, and never enter the deck',()=>{
  let g=supplies(weaponBattle(),['knife','spear']),p=g.players[0];const [knife,spear]=p.bag,actions=g.actions;g=apply(g,'battlePlan',{cards:['weapon:'+knife.id,0,'weapon:'+spear.id]});assert.equal(g.players[0].combatHand.length,3);assert.equal(g.actions,actions-1);assert.equal(g.players[0].bag[0].durability,6);g=apply(g,'battleStep');assert.equal(g.battleEffect.power,2);assert.equal(g.battleEffect.damage,2);assert.equal(g.battleEffect.card.kind,'knife');assert.deepEqual(g.players[0].bag.map(i=>i.durability),[5,6]);g=apply(g,'battleStep');assert.deepEqual(g.players[0].bag.map(i=>i.durability),[5,6]);g=apply(g,'battleStep');assert.deepEqual(g.players[0].bag.map(i=>i.durability),[5,5]);assert.equal(g.battle.stage,'choice');assert.equal(g.players[0].combatHand.length,4);assert.ok(combatPile(g.players[0]).every(c=>typeof c==='string'&&E.COMBAT[c]));g=apply(g,'battleStop');assert.equal(combatPile(g.players[0]).length,10);assert.equal(E.combatOptions(g.players[0]).length,6);assert.deepEqual(E.migrateSave(g),g);
});
test('early kills leave unplayed weapon cards and durability untouched',()=>{
  let g=supplies(weaponBattle(),['knife','spear']);g.battle.hp=1;const [knife,spear]=g.players[0].bag;g=apply(g,'battlePlan',{cards:[0,'weapon:'+knife.id,'weapon:'+spear.id]});g=apply(g,'battleStep');assert.equal(g.battle,null);assert.ok(g.huntResult);assert.deepEqual(g.players[0].bag.map(i=>i.durability),[6,6]);assert.equal(g.players[0].combatHand.length,4);assert.equal(combatPile(g.players[0]).length,10);assert.equal(g.players[0].combatDiscard.length,1);
});
test('the last weapon durability breaks only that weapon and save reload resumes the remaining plan',()=>{
  let g=supplies(weaponBattle(),['knife','spear']);const [knife,spear]=g.players[0].bag;knife.durability=1;g=apply(g,'battlePlan',{cards:['weapon:'+knife.id,0,'weapon:'+spear.id]});g=apply(g,'battleStep');assert.equal(g.players[0].bag.some(i=>i.id===knife.id),false);assert.equal(g.battleEffect.weapons[0].broken,true);assert.equal(E.combatOptions(g.players[0]).filter(o=>typeof o.selection==='string').length,1);const save=E.clone(g);g=E.migrateSave(JSON.parse(JSON.stringify(g)));assert.deepEqual(g,save);g=apply(g,'battleStep');g=apply(g,'battleStep');assert.equal(g.players[0].bag[0].durability,5);assert.equal(g.battle.stage,'choice');g=apply(g,'battleContinue');assert.equal(E.combatOptions(g.players[0]).filter(o=>typeof o.selection==='string').length,1);assert.ok(combatPile(g.players[0]).every(c=>E.COMBAT[c]));
});
test('duplicate, missing, broken, unreceived and foreign weapon selections fail without spending',()=>{
  for(const scenario of ['duplicate','missing','broken','foreign','unreceived']){let g=supplies(weaponBattle(2),['knife']);const id=g.players[0].bag[0].id;if(scenario==='broken')g.players[0].bag[0].durability=0;if(scenario==='foreign')g.players[1].bag.push(g.players[0].bag.shift());if(scenario==='unreceived')g.loot.push({...g.players[0].bag.shift(),owner:0});const key='weapon:'+(scenario==='missing'?'missing':id),cards=scenario==='duplicate'?[key,key,0]:[key,0,1],before=E.clone(g);assert.throws(()=>E.act(g,'battlePlan',{cards}));assert.deepEqual(g,before);}
});
test('allied weapon support spends the ally item once and preserves both basic decks',()=>{
  let g=weaponBattle(2);supplies(g,['spear'],g.players[0]);supplies(g,['knife'],g.players[1]);const ally=g.players[1].bag[0];g=apply(g,'battleAssist',{player:1,card:'weapon:'+ally.id});assert.equal(g.players[1].combatHand.length,4);assert.equal(g.players[1].bag[0].durability,6);g=apply(g,'battlePlan',{cards:[0,1,2]});g=apply(g,'battleStep');assert.equal(g.battleEffect.power,3);assert.equal(g.battleEffect.weapons[0].player,1);assert.equal(g.players[0].bag[0].durability,6);assert.equal(g.players[1].bag[0].durability,5);g=apply(g,'battleStep');g=apply(g,'battleStep');g=apply(g,'battleStop');assert.equal(combatPile(g.players[0]).length,10);assert.equal(combatPile(g.players[1]).length,10);assert.equal(g.players[1].combatHand.length,4);
});
